import React, { useEffect, useState } from 'react';
import { Bar } from 'react-chartjs-2';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
} from 'chart.js';
import axios from 'axios';

ChartJS.register(CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend);

function Dashboard() {
  const [stats, setStats] = useState({ total_scans: 0, malware_detected: 0, vulnerability_reports: 0 });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    axios.get('/api/stats/summary')
      .then((res) => {
        setStats(res.data);
      })
      .catch(() => {
        // ignore for now
      })
      .finally(() => setLoading(false));
  }, []);

  const chartData = {
    labels: ['Total Scans', 'Malware Detections', 'Vulnerability Reports'],
    datasets: [
      {
        label: 'Events',
        data: [stats.total_scans, stats.malware_detected, stats.vulnerability_reports],
        backgroundColor: ['#17a2b8', '#dc3545', '#ffc107'],
      },
    ],
  };

  return (
    <div>
      <div className="d-flex justify-content-between align-items-center mb-3">
        <h2>Security Operations Dashboard</h2>
        {loading && <span className="badge bg-secondary">Loading...</span>}
      </div>

      <div className="row">
        <div className="col-md-4">
          <div className="card bg-dark text-white mb-3">
            <div className="card-body">
              <h5 className="card-title">Total Scans</h5>
              <p className="display-6">{stats.total_scans}</p>
            </div>
          </div>
        </div>
        <div className="col-md-4">
          <div className="card bg-dark text-white mb-3">
            <div className="card-body">
              <h5 className="card-title">Malware Detections</h5>
              <p className="display-6">{stats.malware_detected}</p>
            </div>
          </div>
        </div>
        <div className="col-md-4">
          <div className="card bg-dark text-white mb-3">
            <div className="card-body">
              <h5 className="card-title">Vuln Reports</h5>
              <p className="display-6">{stats.vulnerability_reports}</p>
            </div>
          </div>
        </div>
      </div>

      <div className="card bg-dark text-white">
        <div className="card-body">
          <h5 className="card-title">Trend Overview</h5>
          <Bar data={chartData} options={{ responsive: true, plugins: { legend: { display: false } } }} />
        </div>
      </div>
    </div>
  );
}

export default Dashboard;
